# -*- coding: utf-8 -*-
# Счета на платёж 2 (45% доли, утверждение ядра, 450 000 ₸): BUB-С-2026-04 (Тимур) и BUB-С-2026-05 (Талгат).
# Строится из счетов предоплаты app/schet-bubnovsky-{slug}.html (их собирает schet.py).
import os,re
ROOT=os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)),'..','..','..','..'))
for slug,old,new,num in (('timur','BUB-С-2026-01','BUB-С-2026-04','BUB-2026-01'),('talgat','BUB-С-2026-02','BUB-С-2026-05','BUB-2026-02')):
    s=open(ROOT+f'/app/schet-bubnovsky-{slug}.html',encoding='utf-8').read()
    R=[('предоплата 1 из 3','платёж 2 из 3'),('от 27 октября 2026 г.<br>Действителен до 10.11.2026','от 4 ноября 2026 г.<br>Действителен до 11.11.2026'),
     ('ПЛАТЁЖ 1 · ПРЕДОПЛАТА 10% ДОЛИ · СТАРТ РАБОТ','ПЛАТЁЖ 2 · 45% ДОЛИ · УТВЕРЖДЕНИЕ ЯДРА СИСТЕМЫ'),
     (f'Предоплата по <b>Договору № {num} от 27.10.2026</b> (п. 2.4)',f'Второй платёж по <b>Договору № {num} от 27.10.2026</b> (п. 2.4, п. 3.2) — после утверждения ядра Системы'),
     ('Работы начинаются в рабочий день, следующий за поступлением предоплаты от обоих заказчиков (п. 2.5).','Предоплата 10% (100 000 ₸) получена. Оплата — в течение 5 рабочих дней с даты акта утверждения ядра.'),
     ('НАЗНАЧЕНИЕ ПЛАТЕЖА · ПРЕДОПЛАТА 10% ДОЛИ (50%)','НАЗНАЧЕНИЕ ПЛАТЕЖА · 45% ДОЛИ (50%) · ЯДРО СИСТЕМЫ'),
     (f'<b>Предоплата 10% доли Заказчика за разработку программного обеспечения по Договору № {num} от 27.10.2026.</b>',f'<b>Платёж 2 — 45% доли Заказчика за разработку программного обеспечения по Договору № {num} от 27.10.2026, утверждение ядра Системы (п. 3.2).</b>'),
     ('<td class="r">100 000,00</td>','<td class="r">450 000,00</td>'),
     ('<div class="step cur"><span>Платёж 1 · 10% — предоплата, старт работ<span class="tg">← настоящий счёт</span></span><span>100 000 ₸</span></div>\n    <div class="step"><span>Платёж 2 · 45% — утверждение ядра Системы</span><span>450 000 ₸</span></div>',
      f'<div class="step"><span>Платёж 1 · 10% — предоплата, старт работ · оплачено ({old})</span><span>100 000 ₸</span></div>\n    <div class="step cur"><span>Платёж 2 · 45% — утверждение ядра Системы<span class="tg">← настоящий счёт</span></span><span>450 000 ₸</span></div>'),
     ('К ОПЛАТЕ — ПРЕДОПЛАТА 10%<span>1-й из 3 платежей по доле · старт работ</span>','К ОПЛАТЕ — 45% ДОЛИ<span>2-й из 3 платежей по доле · утверждение ядра</span>'),
     ('<span class="pv">100 000 ₸</span>','<span class="pv">450 000 ₸</span>'),
     ('Сто тысяч тенге 00 тиын.','Четыреста пятьдесят тысяч тенге 00 тиын.'),
     (f'Договор № {num} от 27.10.2026, п. 2.4',f'Договор № {num} от 27.10.2026, п. 2.4, платёж 2'),
     (f'Оплата по счёту {old} от 27.10.2026, предоплата 10% по договору',f'Оплата по счёту {new} от 04.11.2026, платёж 2 (45%, утверждение ядра) по договору'),
     ('Дата выставления: 27.10.2026 · Срок оплаты: до 10.11.2026<br>\n      <b>К оплате: 100 000 ₸</b>','Дата выставления: 04.11.2026 · Срок оплаты: до 11.11.2026<br>\n      <b>К оплате: 450 000 ₸</b>'),
     ('· предоплата 10%</span>','· платёж 2 · 45%</span>')]
    for a,b in R:
        assert a in s,(slug,a[:60]);s=s.replace(a,b)
    s=s.replace(old,new)
    s=s.replace(f'оплачено ({new})',f'оплачено ({old})')
    s=re.sub(r'<title>.*?</title>',lambda m:m.group(0).replace('предоплата','платёж 2 · 45%'),s,1)
    open(ROOT+f'/app/schet-bubnovsky-{slug}-2.html','w',encoding='utf-8').write(s)
    print('ok',slug)
